{"path":"/root/create_promo_register_deliverables.py","content":"from pathlib import Path
from datetime import datetime, date
from decimal import Decimal, InvalidOperation
from collections import defaultdict

from openpyxl import Workbook, load_workbook
from docx import Document

SRC = Path('/root/Promo_Price_Check_Source.xlsx')
AUDIT = Path('/root/Promo_Register_Audit.xlsx')
BRIEF = Path('/root/Promo_Register_Brief.docx')

DATE_COLUMNS = {'Promo Start Date', 'Sale Date', 'Promo End Date'}
BASE_COLUMNS = [
    'Promo ID', 'SKU', 'Promo Price', 'Register Price',
    'Promo Start Date', 'Sale Date', 'Promo End Date', 'Store ID'
]
FORMATTED_HEADERS = BASE_COLUMNS + ['Price Error', 'Window Error', 'Total Errors', 'Error Summary']
SUMMARY_HEADERS = ['SKU', 'Store ID', 'Price Errors', 'Window Errors', 'Total Errors']


def cell_to_output_value(value, header):
    """Preserve openpyxl values, but force required date columns to plain strings."""
    if header in DATE_COLUMNS:
        if value is None:
            return None
        if isinstance(value, datetime):
            return value.date().isoformat()
        if isinstance(value, date):
            return value.isoformat()
        return str(value)
    return value


def parse_decimal(value):
    if value is None or value == '':
        return None
    try:
        return Decimal(str(value).strip())
    except (InvalidOperation, AttributeError):
        return None


def parse_date_for_compare(value):
    if value is None or value == '':
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value).strip()
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%Y/%m/%d', '%m-%d-%Y'):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(text).date()
    except ValueError:
        return None


def error_summary(price_error, window_error):
    if price_error and window_error:
        return 'Price Error, Window Error'
    if price_error:
        return 'Price Error'
    if window_error:
        return 'Window Error'
    return 'None'


def print_source_inspection(rows, headers, ws_title, sheet_names, max_row, max_col):
    print('STEP 1: source workbook inspection')
    print('source:', str(SRC))
    print('sheet names:', sheet_names)
    print('first sheet:', ws_title)
    print('dimensions:', max_row, 'rows x', max_col, 'cols')
    print('headers:', headers)
    print('first 5 rows:')
    for row in rows[:5]:
        print(row)
    print('dtypes by column from non-empty source values:')
    for idx, header in enumerate(headers):
        seen_types = []
        examples = []
        for row in rows[1:]:
            value = row[idx] if idx < len(row) else None
            if value is not None:
                tname = type(value).__name__
                if tname not in seen_types:
                    seen_types.append(tname)
                    examples.append(repr(value))
            if len(seen_types) >= 5:
                break
        print(f'{idx + 1}. {header}: {seen_types or ["NoneType"]}; examples={examples[:3]}')
    print()


def read_source_with_openpyxl():
    wb = load_workbook(SRC, data_only=False, read_only=True)
    ws = wb[wb.sheetnames[0]]
    rows = [list(row) for row in ws.iter_rows(values_only=True)]
    sheet_names = list(wb.sheetnames)
    title = ws.title
    max_row = ws.max_row
    max_col = ws.max_column
    wb.close()
    if not rows:
        raise ValueError('Source workbook has no rows')
    headers = rows[0]
    return rows, headers, title, sheet_names, max_row, max_col


def main():
    rows, headers, title, sheet_names, max_row, max_col = read_source_with_openpyxl()
    print_source_inspection(rows, headers, title, sheet_names, max_row, max_col)

    header_index = {header: idx for idx, header in enumerate(headers)}
    missing = [col for col in BASE_COLUMNS if col not in header_index]
    if missing:
        raise ValueError(f'Missing required source columns: {missing}')

    out_wb = Workbook()
    raw_ws = out_wb.active
    raw_ws.title = 'RawData'
    formatted_ws = out_wb.create_sheet('Formatted Data')
    summary_ws = out_wb.create_sheet('Summary')

    # RawData: write all source cells in source order. Required date columns are plain strings.
    for source_row in rows:
        output_row = [
            cell_to_output_value(source_row[i] if i < len(source_row) else None, headers[i] if i < len(headers) else None)
            for i in range(len(headers))
        ]
        raw_ws.append(output_row)

    formatted_ws.append(FORMATTED_HEADERS)

    totals = {'price': 0, 'window': 0, 'total': 0}
    group_totals = defaultdict(lambda: {'price': 0, 'window': 0, 'total': 0})
    sku_totals = defaultdict(lambda: {'price': 0, 'window': 0, 'total': 0})

    for source_row in rows[1:]:
        row_map = {
            header: (source_row[idx] if idx < len(source_row) else None)
            for header, idx in header_index.items()
        }

        promo_price = parse_decimal(row_map['Promo Price'])
        register_price = parse_decimal(row_map['Register Price'])
        price_error = int(promo_price is not None and register_price is not None and promo_price != register_price)

        sale_date = parse_date_for_compare(row_map['Sale Date'])
        start_date = parse_date_for_compare(row_map['Promo Start Date'])
        end_date = parse_date_for_compare(row_map['Promo End Date'])
        window_error = int(
            sale_date is not None and start_date is not None and end_date is not None
            and (sale_date < start_date or sale_date > end_date)
        )

        total_errors = price_error + window_error
        summary = error_summary(price_error, window_error)

        base_values = [cell_to_output_value(row_map[col], col) for col in BASE_COLUMNS]
        formatted_ws.append(base_values + [price_error, window_error, total_errors, summary])

        sku = row_map['SKU']
        store_id = row_map['Store ID']
        key = (sku, store_id)
        group_totals[key]['price'] += price_error
        group_totals[key]['window'] += window_error
        group_totals[key]['total'] += total_errors
        sku_totals[sku]['price'] += price_error
        sku_totals[sku]['window'] += window_error
        sku_totals[sku]['total'] += total_errors
        totals['price'] += price_error
        totals['window'] += window_error
        totals['total'] += total_errors

    summary_ws.append(SUMMARY_HEADERS)
    error_groups = [
        (sku, store_id, vals)
        for (sku, store_id), vals in group_totals.items()
        if vals['total'] > 0
    ]
    error_groups.sort(key=lambda item: ('' if item[0] is None else str(item[0]), '' if item[1] is None else str(item[1])))
    for sku, store_id, vals in error_groups:
        summary_ws.append([sku, store_id, vals['price'], vals['window'], vals['total']])
    summary_ws.append(['Grand Total', '-', totals['price'], totals['window'], totals['total']])

    # Keep required date columns explicitly text-formatted in both output data sheets.
    for ws in (raw_ws, formatted_ws):
        header_row = [cell.value for cell in ws[1]]
        for col_num, header in enumerate(header_row, start=1):
            if header in DATE_COLUMNS:
                for cell in ws.iter_cols(min_col=col_num, max_col=col_num, min_row=2, max_row=ws.max_row):
                    for c in cell:
                        c.number_format = '@'

    out_wb.save(AUDIT)
    print('Wrote Excel audit workbook:', str(AUDIT))

    sorted_skus = sorted(
        [(sku, vals) for sku, vals in sku_totals.items()],
        key=lambda item: (-item[1]['total'], '' if item[0] is None else str(item[0]))
    )
    top_sku_names = [str(sku) for sku, vals in sorted_skus if vals['total'] > 0][:2]
    if len(top_sku_names) < 2:
        top_sku_names = [str(sku) for sku, vals in sorted_skus[:2]]
    top_sku_text = ' and '.join(top_sku_names) if top_sku_names else 'no SKU'

    doc = Document()
    doc.add_heading('Promo Register Audit Brief', level=1)
    paragraph = doc.add_paragraph()
    paragraph.add_run(
        'A Price Error means the register price does not match the configured promo price, while a Window Error means the sale occurred before the promo start date or after the promo end date. '
    )
    paragraph.add_run(
        f'The audit found {totals["price"]} Price Errors, {totals["window"]} Window Errors, and {totals["total"]} Total Errors across all formatted rows. '
    )
    paragraph.add_run(
        f'The SKUs with the highest error counts include {top_sku_text}, so those items should be prioritized for register and promotion-window review. '
    )
    paragraph.add_run(
        'As an actionable next step, reconcile promo setup records against register price files before each promotion launches and add an exception report for sales outside active promo windows. '
    )
    paragraph.add_run(
        'Stores with repeated SKU-level exceptions should receive a targeted price-file refresh and a follow-up scan audit.'
    )
    doc.save(BRIEF)
    print('Wrote Word brief:', str(BRIEF))

    # Step 3 validation.
    print('\nSTEP 3: validation')
    check_wb = load_workbook(AUDIT, data_only=True, read_only=False)
    print('sheet names:', check_wb.sheetnames)
    for sheet_name in check_wb.sheetnames:
        ws = check_wb[sheet_name]
        print(f'first 3 rows of {sheet_name}:')
        for row in ws.iter_rows(min_row=1, max_row=min(3, ws.max_row), values_only=True):
            print(list(row))
    date_cell_value = check_wb['RawData']['E2'].value
    print('RawData E2 date cell value:', repr(date_cell_value), 'type:', type(date_cell_value).__name__)
    summary_sheet = check_wb['Summary']
    last_summary_row = [cell.value for cell in summary_sheet[summary_sheet.max_row]]
    print('Summary last row:', last_summary_row)
    check_wb.close()

    print('brief exists:', BRIEF.exists(), 'size:', BRIEF.stat().st_size if BRIEF.exists() else None)
    read_doc = Document(BRIEF)
    doc_text = '\n'.join(paragraph.text for paragraph in read_doc.paragraphs if paragraph.text)
    print('brief text:')
    print(doc_text)


if __name__ == '__main__':
    main()
